require_once '../config/app.php';require_once '../includes/security.php';start_secure_session();require_user();$pdo=db();$uid=(int)$_SESSION['user_id'];$error=null;
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!csrf_check($_POST['_csrf']??''))$error='Invalid request.';
 else{try{$action=$_POST['action']??'add';if($action==='delete'){$pdo->prepare("DELETE FROM user_education WHERE id=? AND user_id=?")->execute([(int)$_POST['id'],$uid]);}
 elseif($action==='add'){$pdo->prepare("INSERT INTO user_education(user_id,qualification_type,course_name,stream,board_university,institution,passing_year,marks,percentage,cgpa,roll_number,registration_number) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)")->execute([$uid,trim($_POST['qualification_type']),trim($_POST['course_name']),trim($_POST['stream']),trim($_POST['board_university']),trim($_POST['institution']),$_POST['passing_year']?:null,trim($_POST['marks']),$_POST['percentage']!==''?(float)$_POST['percentage']:null,trim($_POST['cgpa']),trim($_POST['roll_number']),trim($_POST['registration_number'])]);}
flash('success',$action==='delete'?'Education record deleted.':'Education record added.');redirect('education.php');}catch(Throwable $e){$error='Could not save education record.';}}}
$st=$pdo->prepare("SELECT * FROM user_education WHERE user_id=? ORDER BY passing_year DESC,id DESC");$st->execute([$uid]);$rows=$st->fetchAll();
$page_title='Education';$asset_prefix='../';$home_link='../index.php';require '../includes/header.php';?>
<div class="page-head"><div><h1>Education</h1><p class="muted">Add all qualifications that may affect government-job eligibility.</p></div><a class="btn btn-light" href="profile.php">← Profile</a></div>
