<div class="card"><h2>Add Education</h2><form class="form-grid" method="post"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="add">
<label>Qualification<select name="qualification_type" required><option value="">Select</option><?php foreach(['10th','12th','ITI','Diploma','Graduation','Post Graduation','Professional','Other'] as $x):?><option><?=e($x)?></option><?php endforeach;?></select></label>
<label>Course / Degree<input name="course_name"></label><label>Stream / Specialization<input name="stream"></label><label>Board / University<input name="board_university"></label><label>Institution<input name="institution"></label><label>Passing Year<input type="number" name="passing_year" min="1950" max="2100"></label><label>Marks<input name="marks"></label><label>Percentage<input type="number" step="0.01" name="percentage"></label><label>CGPA<input name="cgpa"></label><label>Roll Number<input name="roll_number"></label><label>Registration Number<input name="registration_number"></label>
